async function prototypes(roots){const views={},entries={},menus={};for(const[size,d]of Object.entries(sizes)){for(const type of ['home','case']){const src=roots[type+size],v=box('Prototype / '+type+' / '+size,d.w,'VERTICAL',0,0,'paper');product.appendChild(v);fix(v,d.w,size==='Desktop'?900:size==='Tablet'?1024:844);v.clipsContent=true;v.overflowDirection='VERTICAL';v.x=4200+(size==='Desktop'?0:size==='Tablet'?1600:2500);v.y=2000+(type==='case'?1400:0);put(v,track(src.clone()));views[type+size]=v;S.prototypes[type+size]=v.id;}}
const target=(r,name)=>r.findOne(n=>n.type==='FRAME'&&n.name===name);const named=(r,name)=>r.findAll(n=>n.name===name);for(const[size,d]of Object.entries(sizes)){for(const[i,title]of ['Услуги','Команда','Заявка','Работы'].entries()){const v=track(views['home'+size].clone());product.appendChild(v);v.name='Entry / '+size+' / '+title;v.x=7500+(size==='Desktop'?0:size==='Tablet'?1600:2500);v.y=80+i*1200;entries[size+title]=v;link(v,target(v,title),'SCROLL_TO',{type:'AFTER_TIMEOUT',timeout:.01});}if(size!=='Desktop'){const menu=box('Overlay / Menu / '+size,d.w,'VERTICAL',0,0,'paper');product.appendChild(menu);put(menu,instance(K.menus[size]),true);menu.x=7500+(size==='Tablet'?0:900);menu.y=5200;menus[size]=menu;named(menu,'Menu close').forEach(close);for(const title of ['Услуги','Работы','Команда','Заявка'])named(menu,'Menu / '+title).forEach(n=>link(n,entries[size+title],'NAVIGATE'));}}
function wire(root,key){const size=Object.keys(sizes).find(s=>key.endsWith(s)),isCase=key.startsWith('case');for(const title of ['Услуги','Команда','Заявка'])named(root,'Nav / '+title).forEach(n=>link(n,isCase?entries[size+title]:target(root,title),isCase?'NAVIGATE':'SCROLL_TO'));named(root,'Action / Обсудить задачу').forEach(n=>link(n,isCase?entries[size+'Заявка']:target(root,'Заявка'),isCase?'NAVIGATE':'SCROLL_TO'));named(root,'Work / Featured').forEach(n=>link(n,views['case'+size],'NAVIGATE'));named(root,'Case / Back').forEach(n=>link(n,entries[size+'Работы'],'NAVIGATE'));named(root,'Home logo').forEach(n=>link(n,views['home'+size],'NAVIGATE'));if(menus[size])named(root,'Menu toggle').forEach(n=>link(n,menus[size],'OVERLAY'));}
for(const [key,v]of Object.entries(views))wire(v,key);for(const [key,v]of Object.entries(roots))wire(v,key);for(const[size,d]of Object.entries(sizes))for(const title of ['Услуги','Команда','Заявка','Работы'])wire(entries[size+title],'home'+size);
const formTests=[];for(const[size,d]of Object.entries(sizes)){for(const[mode,index]of [['Ошибка',2],['Заполнена',1],['Отправка',3],['Успех',4],['Сбой',5]]){const f=box('Form scenario / '+size+' / '+mode,d.w,'VERTICAL',24,d.p,'paper');product.appendChild(f);f.x=11200+(size==='Desktop'?0:size==='Tablet'?1600:2500);f.y=80+formTests.filter(x=>x.size===size).length*1300;label(f,'Форма / '+mode,d.w-d.p*2,24,'Bold','ink',true);put(f,instance(K.forms[size][index]),true);const back=put(f,button('На главную',d.w-d.p*2));link(back,views['home'+size],'NAVIGATE');formTests.push({size,mode,id:f.id});}}
product.flowStartingPoints=[...Object.keys(sizes).map(size=>({nodeId:views['home'+size].id,name:'Сайт · '+size})),...Object.keys(sizes).map(size=>({nodeId:views['case'+size].id,name:'Кейс · '+size})),{nodeId:formTests.find(x=>x.size==='Mobile'&&x.mode==='Сбой').id,name:'Форма · Сбой и повтор'}];S.entries=Object.fromEntries(Object.entries(entries).map(([k,n])=>[k,n.id]));S.menus=Object.fromEntries(Object.entries(menus).map(([k,n])=>[k,n.id]));S.formScenarios=formTests;await flush();return views;}
